CREATE OR REPLACE FUNCTION public.runtime_work_projection_before_opc(p_actor_id uuid, p_session_id uuid, p_round_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE s runtime_sessions;r artifact_rounds;v jsonb;source jsonb;ref jsonb;
BEGIN
 SELECT * INTO s FROM runtime_sessions WHERE id=p_session_id AND actor_id=p_actor_id;
